{"code": "import json, glob, os, shutil

files = glob.glob('/app/config/**/*.json', recursive=True)

def rename(o):
    if isinstance(o, dict):
        return {('max_retries' if k == 'retries' else k): rename(v) for k, v in o.items()}
    if isinstance(o, list):
        return [rename(x) for x in o]
    return o

for f in files:
    orig = open(f).read()
    data = json.loads(orig)
    new = rename(data)
    newtxt = json.dumps(new, indent=2, ensure_ascii=False) + "\n"
    # sanity: reverse-rename must equal original data
    def back(o):
        if isinstance(o, dict):
            return {('retries' if k == 'max_retries' else k): back(v) for k, v in o.items()}
        if isinstance(o, list):
            return [back(x) for x in o]
        return o
    assert back(new) == json.loads(orig), f
    if newtxt != orig:
        open(f, 'w').write(newtxt)
        print("WROTE", f)
    else:
        print("no change", f)

# report
for f in files:
    t = open(f).read()
    json.loads(t)
    print("\n---", f)
    print(t)
"}

