{"content": """"Minimal YAML subset loader (enough for config/services.yaml).

Implements: block mappings/sequences by indentation, flow mappings ({k: v, ...}),
anchors (&x) / aliases (*x), merge keys (<<), comments, quoted/int/bool scalars.
Only used because PyYAML is unavailable offline in this environment.
"""


def _strip_comment(s):
    out = []
    q = None
    i = 0
    while i < len(s):
        c = s[i]
        if q:
            out.append(c)
            if c == q:
                q = None
        else:
            if c in "'\"":
                q = c
                out.append(c)
            elif c == "#" and (i == 0 or s[i - 1] in " \t"):
                break
            else:
                out.append(c)
        i += 1
    return "".join(out).rstrip()


def _split_flow(s):
    parts, depth, q, cur = [], 0, None, []
    for c in s:
        if q:
            cur.append(c)
            if c == q:
                q = None
        elif c in "'\"":
            q = c
            cur.append(c)
        elif c in "{[":
            depth += 1
            cur.append(c)
        elif c in "}]":
            depth -= 1
            cur.append(c)
        elif c == "," and depth == 0:
            parts.append("".join(cur))
            cur = []
        else:
            cur.append(c)
    if "".join(cur).strip():
        parts.append("".join(cur))
    return parts


class Loader:
    def __init__(self, text):
        self.anchors = {}
        self.lines = []
        for raw in text.splitlines():
            if not raw.strip() or raw.strip().startswith("#"):
                continue
            c = _strip_comment(raw)
            if not c.strip():
                continue
            indent = len(c) - len(c.lstrip(" "))
            self.lines.append((indent, c.strip()))
        self.i = 0

    def _scalar(self, s):
        s = s.strip()
        if s.startswith("&"):
            name, _, rest = s[1:].partition(" ")
            val = self._ok(rest.strip()) if rest.strip() else None
            self.anchors[name] = val
            return val
        if s.startswith("*"):
            return self.anchors[s[1:].strip()]
        if s.startswith("{"):
            return self._flow_map(s)
        if s.startswith("["):
            return [self._ok(p) for p in _split_flow(s[1:-1])]
        return self._flat(s)

    def _ok(self, s):
        # scalar without anchor handling
        s = s.strip()
        if s.startswith("{"):
            return self._flow_map(s)
        if s.startswith("["):
            return [self._ok(p) for p in _split_flow(s[1:-1])]
        return self._flat(s)

    def _flow_map(self, s):
        inner = s.strip()[1:-1]
        d = {}
        for p in _split_flow(inner):
            k, _, v = p.partition(":")
            d[k.strip()] = self._ok(v)
        return d

    def _flat(self, s):
        if len(s) >= 2 and s[0] == s[-1] and s[0] in "'\"":
            return s[1:-1]
        if s in ("true", "True"):
            return True
        if s in ("false", "False"):
            return False
        if s in ("null", "~", ""):
            return None
        try:
            return int(s)
        except ValueError:
            return s

    def parse(self):
        val, _ = self._block(0, 0)
        return val

    def _block(self, indent, pos):
        if pos >= len(self.lines):
            return None, pos
        ind, content = self.lines[pos]
        if content.startswith("- "):
            return self._seq(ind, pos)
        return self._map(ind, pos)

    def _seq(self, indent, pos):
        items = []
        while pos < len(self.lines):
            ind, content = self.lines[pos]
            if ind != indent or not content.startswith("- "):
                break
            rest = content[2:].strip()
            # item content begins at column indent+2
            sub_indent = indent + 2
            if ":" in rest and not rest.startswith(("{", "[")):
                # build a mapping starting with this line
                saved = self.lines
                self.lines = saved[:pos] + [(sub_indent, rest)] + saved[pos + 1:]
                m, npos = self._map(sub_indent, pos)
                self.lines = saved
                pos = npos
                items.append(m)
            else:
                items.append(self._ok(rest))
                pos += 1
        return items, pos

    def _map(self, indent, pos):
        d = {}
        merges = []
        while pos < len(self.lines):
            ind, content = self.lines[pos]
            if ind != indent or content.startswith("- "):
                break
            key, _, rest = content.partition(":")
            key = key.strip()
            rest = rest.strip()
            pos += 1
            if key == "<<":
                vals = rest if isinstance(rest, str) else rest
                src = self._ok(rest) if rest else None
                if rest.startswith("["):
                    srcs = [self._ok(p) for p in _split_flow(rest[1:-1])]
                else:
                    srcs = [src]
                for s in srcs:
                    merges.append(s)
                continue
            if rest:
                d[key] = self._scalar(rest)
            else:
                val, pos = self._block_child(indent, pos)
                d[key] = val
        for m in merges:
            if isinstance(m, dict):
                for k, v in m.items():
                    d.setdefault(k, v)
        return d, pos

    def _block_child(self, indent, pos):
        if pos < len(self.lines) and self.lines[pos][0] > indent:
            return self._block(self.lines[pos][0], pos)
        return None, pos


def safe_load(text):
    return Loader(text).parse()
