def varint(buf,off):
    v=0
    for i in range(9):
        b=buf[off+i]
        v=(v<<7)|(b&0x7f)
        if not (b&0x80):
            return v,off+i+1
    return v,off+9

def serial(t):
    if t==0: return ('null',0)
    if t in (1,2,3,4,5,6): return ('int',{1:1,2:2,3:3,4:4,5:6,6:8}[t])
    if t==7: return ('int',8)
    if t==8: return ('int',0)
    if t==9: return ('int',0)
    if t>=12:
        if t%2==0: return ('blob',(t-12)//2)
        else: return ('text',(t-13)//2)
    return ('?',0)

