{"content": "#!/usr/bin/env python3
"""Differential tester: run COBOL binary and /app/program.py on identical
input states and compare resulting data files byte-for-byte."""
import os, random, shutil, subprocess, sys, tempfile
from pathlib import Path

COB = Path("/tmp/hermes/cache/scratch/cob/bookforum")
PY = "/app/program.py"
NUM_RUNS = int(sys.argv[1]) if len(sys.argv) > 1 else 200
SEED = int(sys.argv[2]) if len(sys.argv) > 2 else 1

def mk_account(acc_id, name, bal):
    return (acc_id.ljust(4)[:4] + name.ljust(20)[:20] + str(bal).zfill(10)).encode()

def mk_book(bid, title, owner):
    return (bid.ljust(4)[:4] + title.ljust(20)[:20] + owner.ljust(4)[:4]).encode()

def mk_trans(book, amt, seller, buyer):
    return (book.ljust(4)[:4] + str(amt).zfill(10) + seller.ljust(4)[:4] + buyer.ljust(4)[:4]).encode()

def gen_scenario(rng):
    nacc = rng.randint(1, 4)
    accounts = []
    for i in range(nacc):
        accounts.append(mk_account("U%03d" % i, "Name %d" % i, rng.randint(0, 5000)))
    nbook = rng.randint(1, 4)
    books = []
    for i in range(nbook):
        owner = "U%03d" % rng.randrange(nacc)
        books.append(mk_book("B%03d" % i, "Title %d" % i, owner))
    trans = bytearray()
    for _ in range(rng.randint(0, 3)):
        trans += mk_trans("B%03d" % rng.randrange(nbook), rng.randint(0, 500),
                          "U%03d" % rng.randrange(nacc), "U%03d" % rng.randrange(nacc))
    # input: sometimes valid, sometimes not
    buyer = "U%03d" % rng.randrange(nacc)
    seller = "U%03d" % rng.randrange(nacc)
    book = "B%03d" % rng.randrange(nbook)
    amt = rng.choice([0, 1, 20, 50, 150, 999, 1000, 5000, 9999999999])
    inp = (buyer + seller + book + str(amt).zfill(10)).encode()
    return {"ACCOUNTS.DAT": bytes(b"".join(accounts)),
            "BOOKS.DAT": bytes(b"".join(books)),
            "TRANSACTIONS.DAT": bytes(trans)}, inp

def run_one(scenario, inp):
    base = Path(tempfile.mkdtemp())
    try:
        for side in ("cob", "py"):
            d = base / side
            (d / "data").mkdir(parents=True)
            (d / "src").mkdir(parents=True)
            for name, data in scenario.items():
                (d / "data" / name).write_bytes(data)
            (d / "src" / "INPUT.DAT").write_bytes(inp)
        r1 = subprocess.run([str(COB)], cwd=base / "cob", capture_output=True)
        r2 = subprocess.run([sys.executable, PY], cwd=base / "py", capture_output=True)
        out = {}
        for name in scenario:
            a = (base / "cob" / "data" / name).read_bytes()
            b = (base / "py" / "data" / name).read_bytes()
            out[name] = (a, b)
        return out, r1, r2
    finally:
        shutil.rmtree(base, ignore_errors=True)

def main():
    rng = random.Random(SEED)
    fails = 0
    for i in range(NUM_RUNS):
        scenario, inp = gen_scenario(rng)
        out, r1, r2 = run_one(scenario, inp)
        bad = {n: v for n, v in out.items() if v[0] != v[1]}
        if bad or r2.returncode != 0:
            fails += 1
            print("FAIL seed=%d iter=%d" % (SEED, i))
            print("  input:", inp)
            print("  scenario:", {k: v for k, v in scenario.items()})
            for n, (a, b) in bad.items():
                print("  %s\n    cob=%r\n    py =%r" % (n, a, b))
            if r2.returncode != 0:
                print("  py stderr:", r2.stderr.decode()[:500])
            if fails > 5:
                break
    print("done: %d runs, %d failures" % (NUM_RUNS, fails))
    return 1 if fails else 0

sys.exit(main())
", "path": "/tmp/hermes/cache/scratch/difftest.py"}

