from pathlib import Path
from collections import Counter
from datetime import date, timedelta

logs = sorted(Path("/app/logs").glob("*.log"))
ref = date(2025,8,12)
per_file = {}
for p in logs:
    d = date.fromisoformat(p.name[:10])
    c = Counter()
    for line in p.read_text(errors="replace").splitlines():
        m = re.search(r'\[(ERROR|WARNING|INFO)\]', line)
        if m:
            c[m.group(1)] += 1
    per_file[d] = c

periods = {
 "today": lambda d: d == ref,
 "last_7_days": lambda d: ref-timedelta(days=6) <= d <= ref,
 "last_30_days": lambda d: ref-timedelta(days=29) <= d <= ref,
 "month_to_date": lambda d: d.year==ref.year and d.month==ref.month and d <= ref,
 "total": lambda d: True,
}
sev = ["ERROR","WARNING","INFO"]
rows = [["period","severity","count"]]
for name, fn in periods.items():
    tot = Counter()
    for d,c in per_file.items():
        if fn(d):
            for s in sev: tot[s]+=c[s]
    for s in sev:
        rows.append([name, s, tot[s]])
with open("/app/summary.csv","w",newline="") as f:
    csv.writer(f).writerows(rows)
for r in rows: print(r)
"}

