    if not realdate(r["order_date"]): add("orders",i,"order_date","date")
    if r["status"] not in ("placed","paid","shipped","cancelled"): add("orders",i,"status","enum")
    tv=num(r["total"])
    if tv is None or tv<0: add("orders",i,"total","range")

# order_items
for i,r in enumerate(oi,1):
    if r["order_id"] not in order_ids: add("order_items",i,"order_id","foreign_key")
    if r["sku"] not in prod_ids: add("order_items",i,"sku","foreign_key")
    qv=num(r["qty"])
    if qv is None or qv!=int(qv) or qv<1: add("order_items",i,"qty","range")
